// Tournament roster validation: size limits, starters, captain, one team per player, minors rule.
// Pure: callers pass facts (isMinor, other-team memberships) and decide how to enforce the result.

/** Validate tournament-level limits (what an organizer configures). Returns [{ code, message }]. */
function validateLimits(rules) {
  const errors = [];
  const { minPlayers, maxPlayers, startersPerTeam } = rules;
  const isCount = (v) => Number.isInteger(v) && v >= 1;
  if (!isCount(minPlayers)) errors.push({ code: 'INVALID_MIN_PLAYERS', message: 'minPlayers must be a positive integer' });
  if (!isCount(maxPlayers)) errors.push({ code: 'INVALID_MAX_PLAYERS', message: 'maxPlayers must be a positive integer' });
  if (!isCount(startersPerTeam)) errors.push({ code: 'INVALID_STARTERS', message: 'startersPerTeam must be a positive integer' });
  if (errors.length) return errors;
  if (minPlayers > maxPlayers) errors.push({ code: 'MIN_GREATER_THAN_MAX', message: 'minPlayers must not exceed maxPlayers' });
  if (startersPerTeam > minPlayers) errors.push({ code: 'STARTERS_EXCEED_MIN', message: 'startersPerTeam must not exceed minPlayers' });
  return errors;
}

/**
 * Validate one team's roster.
 * roster: { captainId, members: [{ userId, isMinor?, isStarter? }] } (members that count: accepted, not pending invites).
 * rules: { minPlayers, maxPlayers, startersPerTeam, allowMinors? (default true), requireCaptain? (default true) }.
 * context:
 *   - enforceMin (default true): set false while a team is still forming (registration); max is always enforced.
 *   - requireStarters (default false): true to require exactly startersPerTeam members flagged isStarter (match-day lineup).
 *   - memberships: { [userId]: teamId } of players already on a team in this tournament.
 *   - teamId: this team's id, so a player's own membership is not a clash.
 * Returns { valid, errors: [{ code, message, userId? }] }.
 */
function validateRoster(roster, rules, context = {}) {
  const errors = [];
  const add = (code, message, userId) => errors.push(userId ? { code, message, userId } : { code, message });
  const members = roster.members || [];
  const enforceMin = context.enforceMin !== false;

  limitsOrThrow(rules);

  const seen = new Set();
  members.forEach((m) => {
    if (seen.has(m.userId)) add('DUPLICATE_PLAYER', `player ${m.userId} is listed twice`, m.userId);
    seen.add(m.userId);
  });
  const count = seen.size;

  if (count > rules.maxPlayers) add('TOO_MANY_PLAYERS', `roster has ${count} players, maximum is ${rules.maxPlayers}`);
  if (enforceMin && count < rules.minPlayers) add('TOO_FEW_PLAYERS', `roster has ${count} players, minimum is ${rules.minPlayers}`);

  if (rules.requireCaptain !== false) {
    if (!roster.captainId) add('NO_CAPTAIN', 'a team captain is required');
    else if (!seen.has(roster.captainId)) add('CAPTAIN_NOT_ON_ROSTER', 'the captain must be on the roster', roster.captainId);
  }

  if (rules.allowMinors === false) {
    members.filter((m) => m.isMinor).forEach((m) => add('MINORS_NOT_ALLOWED', `player ${m.userId} is a minor`, m.userId));
  }

  const memberships = context.memberships || {};
  seen.forEach((userId) => {
    const other = memberships[userId];
    if (other !== undefined && other !== context.teamId) {
      add('PLAYER_IN_OTHER_TEAM', `player ${userId} is already on another team in this tournament`, userId);
    }
  });

  const starters = new Set(members.filter((m) => m.isStarter).map((m) => m.userId)).size;
  if (starters > rules.startersPerTeam) {
    add('TOO_MANY_STARTERS', `${starters} starters selected, maximum is ${rules.startersPerTeam}`);
  } else if (context.requireStarters && starters < rules.startersPerTeam) {
    add('TOO_FEW_STARTERS', `${starters} starters selected, ${rules.startersPerTeam} required`);
  }

  return { valid: errors.length === 0, errors };
}

function limitsOrThrow(rules) {
  const problems = validateLimits(rules);
  if (problems.length) throw new Error(`invalid roster rules: ${problems.map((p) => p.code).join(', ')}`);
}

/**
 * Can `candidate` ({ userId, isMinor? }) join this roster? Validates the roster with them added,
 * with the minimum not enforced (the team is still forming). Returns the same shape as validateRoster.
 */
function canAddMember(roster, rules, candidate, context = {}) {
  return validateRoster(
    { ...roster, members: [...(roster.members || []), candidate] },
    rules,
    { ...context, enforceMin: false },
  );
}

module.exports = { validateLimits, validateRoster, canAddMember };
